// Regenerates src/events/index.ts from the files in src/events/ (every <Event>.ts except index/types).
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dir, "..", "src", "events");
const names = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && !["index.ts", "types.ts"].includes(f))
  .map((f) => f.slice(0, -3))
  .sort();
const out = [
  "// Generated by scripts/gen-registry.ts. Do not edit by hand.",
  'import type { EventHandler } from "./types.ts";',
  ...names.map((n) => `import { handler as ${n} } from "./${n}.ts";`),
  "",
  "export const handlers: ReadonlyMap<string, EventHandler> = new Map([",
  ...names.map((n) => `  [${n}.event, ${n}],`),
  "]);",
  "",
].join("\n");
writeFileSync(join(dir, "index.ts"), out);
console.log(`registered ${names.length} handlers`);
